"use client";

import { type FormEvent, useEffect, useMemo, useState } from "react";
import { Activity, Bell, CalendarDays, CheckCircle2, ChevronDown, CircleDollarSign, ClipboardList, Download, Edit3, LoaderCircle, LogOut, PackageSearch, PawPrint, Plus, Printer, ReceiptText, Search, ShoppingCart, ShieldCheck, Users, WalletCards, X } from "lucide-react";
import { createClient, getPublicAppUrl } from "@/lib/supabase/client";
import { downloadTicketPdf, paymentLabel, printTicket } from "@/lib/tickets";
import { prepareSaleRequest, validateProductDraft } from "@/lib/petflow-rules";
import { type DiagnosticResult, summarizeDiagnostics } from "@/lib/petflow-core";

type View = "summary" | "inventory" | "pos" | "sales" | "clients" | "agenda" | "alerts" | "cash" | "diagnostics";
type Product = { id: string; name: string; sku?: string | null; category: string; stock: number; min_stock: number; cost_price: number | string; sale_price: number | string; active: boolean };
type Client = { id: string; full_name: string; phone?: string | null; email?: string | null; notes?: string | null; pets: Pet[] };
type Pet = { id: string; client_id: string; name: string; species: string; breed?: string | null; notes?: string | null };
type Sale = { id: string; client_id?: string | null; payment_method: string; total: number | string; created_at: string; client?: { full_name?: string | null } | null; items: SaleItem[] };
type SaleItem = { sale_id: string; product_name: string; quantity: number; unit_price: number | string; line_total: number | string };
type Appointment = { id: string; client_id: string; pet_id: string; service: string; scheduled_at: string; duration_minutes: number; status: string; notes?: string | null };
type Note = { id: string; title: string; content: string; type: string; read_at?: string | null; created_at: string };
type Shop = { id: string; name: string; timezone: string };
type CartLine = Product & { quantity: number };

const sections: Array<{ id: View; label: string; icon: typeof CircleDollarSign }> = [
  { id: "summary", label: "Resumen", icon: CircleDollarSign }, { id: "inventory", label: "Inventario", icon: PackageSearch }, { id: "pos", label: "Punto de venta", icon: ShoppingCart }, { id: "sales", label: "Ventas", icon: ReceiptText }, { id: "clients", label: "Clientes y mascotas", icon: Users }, { id: "agenda", label: "Agenda", icon: CalendarDays }, { id: "cash", label: "Caja y cierres", icon: WalletCards }, { id: "alerts", label: "Alertas", icon: Bell }, { id: "diagnostics", label: "Diagnóstico", icon: Activity },
];
const categories = ["Alimentos", "Juguetes", "Higiene y salud", "Accesorios", "Descanso", "General"];
const services = ["Baño y peluquería", "Consulta veterinaria", "Vacunación", "Corte de uñas", "Control antiparasitario"];
const formatter = new Intl.NumberFormat("es-AR", { style: "currency", currency: "ARS", maximumFractionDigits: 2 });
const supabase = createClient();

const emptyProduct = { name: "", sku: "", category: categories[0], stock: "0", min_stock: "3", cost_price: "0", sale_price: "", active: true };

export default function PetFlowApp() {
  const [user, setUser] = useState<any>(null); const [shop, setShop] = useState<Shop | null>(null); const [view, setView] = useState<View>("summary");
  const [products, setProducts] = useState<Product[]>([]); const [clients, setClients] = useState<Client[]>([]); const [appointments, setAppointments] = useState<Appointment[]>([]); const [sales, setSales] = useState<Sale[]>([]); const [notes, setNotes] = useState<Note[]>([]); const [settings, setSettings] = useState<any>({ reminders_enabled: true, reminder_lead_minutes: 60 });
  const [loading, setLoading] = useState(false); const [notice, setNotice] = useState(""); const [diagnostics, setDiagnostics] = useState<DiagnosticResult[]>([]); const [modal, setModal] = useState<"product" | "client" | "pet" | "appointment" | "ticket" | null>(null); const [editing, setEditing] = useState<Product | null>(null); const [selectedClient, setSelectedClient] = useState<Client | null>(null); const [selectedTicket, setSelectedTicket] = useState<Sale | null>(null);

  const notify = (message: string) => { setNotice(message); window.setTimeout(() => setNotice(""), 3200); };
  const fail = (error: any) => notify(error?.message || "No fue posible completar la operación.");
  async function runDiagnostics(shopId = shop?.id) {
    const checks: Array<{ name: string; run: () => Promise<{ ok: boolean; detail: string; severity?: DiagnosticResult["severity"] }> }> = [
      { name: "Sesión de creador", run: async () => ({ ok: Boolean((await supabase.auth.getSession()).data.session), detail: "La sesión de Supabase responde." }) },
      { name: "Productos", run: async () => { const result = await supabase.from("products").select("id", { count: "exact", head: true }).eq("pet_shop_id", shopId ?? ""); return { ok: !result.error, detail: result.error?.message ?? `${result.count ?? 0} registros accesibles.` }; } },
      { name: "Ventas", run: async () => { const result = await supabase.from("sales").select("id", { count: "exact", head: true }).eq("pet_shop_id", shopId ?? ""); return { ok: !result.error, detail: result.error?.message ?? `${result.count ?? 0} registros accesibles.` }; } },
      { name: "Avisos", run: async () => { const result = await supabase.from("notifications").select("id", { count: "exact", head: true }).eq("pet_shop_id", shopId ?? ""); return { ok: !result.error, detail: result.error?.message ?? "La bandeja de avisos responde." }; } },
    ];
    const results: DiagnosticResult[] = [];
    for (const check of checks) {
      const started = performance.now();
      try { const result = await check.run(); results.push({ name: check.name, ok: result.ok, severity: result.severity ?? (result.ok ? "info" : "critical"), detail: result.detail, durationMs: Math.round(performance.now() - started) }); }
      catch (error) { results.push({ name: check.name, ok: false, severity: "critical", detail: error instanceof Error ? error.message : "Error desconocido", durationMs: Math.round(performance.now() - started) }); }
    }
    setDiagnostics(results);
  }

  useEffect(() => {
    const fallback = window.setTimeout(() => setLoading(false), 1200);
    void boot().finally(() => window.clearTimeout(fallback));
    return () => window.clearTimeout(fallback);
  }, []);
  async function boot() {
    setLoading(true);
    const code = new URLSearchParams(window.location.search).get("code");
    if (code) {
      const { error } = await supabase.auth.exchangeCodeForSession(code);
      if (error) fail(error);
      window.history.replaceState({}, document.title, window.location.pathname);
    }
    const { data: { session } } = await supabase.auth.getSession();
    const signedInUser = session?.user ?? null;
    setUser(signedInUser);
    if (signedInUser) {
      const { data, error } = await supabase.from("pet_shop_memberships").select("pet_shop:pet_shops(id,name,timezone)").eq("user_id", signedInUser.id).limit(1);
      if (error) fail(error);
      const currentShop = (data?.[0] as any)?.pet_shop as Shop | undefined;
      setShop(currentShop ?? null);
      if (currentShop) { await loadWorkspace(currentShop.id); void runDiagnostics(currentShop.id); }
    }
    setLoading(false);
  }
  async function loadWorkspace(shopId = shop?.id) {
    if (!shopId) return;
    const [productRes, clientRes, petRes, appointmentRes, saleRes, itemRes, noteRes, settingRes] = await Promise.all([
      supabase.from("products").select("*").eq("pet_shop_id", shopId).order("name"),
      supabase.from("clients").select("*").eq("pet_shop_id", shopId).order("full_name"),
      supabase.from("pets").select("*").eq("pet_shop_id", shopId).order("name"),
      supabase.from("appointments").select("*").eq("pet_shop_id", shopId).order("scheduled_at"),
      supabase.from("sales").select("*").eq("pet_shop_id", shopId).order("created_at", { ascending: false }),
      supabase.from("sale_items").select("*").eq("pet_shop_id", shopId),
      supabase.from("notifications").select("*").eq("pet_shop_id", shopId).order("created_at", { ascending: false }).limit(80),
      supabase.from("notification_settings").select("*").eq("pet_shop_id", shopId).maybeSingle(),
    ]);
    const error = [productRes, clientRes, petRes, appointmentRes, saleRes, itemRes, noteRes, settingRes].find(result => result.error)?.error;
    if (error) { fail(error); return; }
    const allPets = (petRes.data ?? []) as Pet[];
    setProducts((productRes.data ?? []) as Product[]);
    setClients(((clientRes.data ?? []) as Omit<Client, "pets">[]).map(client => ({ ...client, pets: allPets.filter(pet => pet.client_id === client.id) })));
    setAppointments((appointmentRes.data ?? []) as Appointment[]);
    setSales(((saleRes.data ?? []) as Sale[]).map(sale => ({ ...sale, client: ((clientRes.data ?? []) as any[]).find((client: any) => client.id === sale.client_id), items: ((itemRes.data ?? []) as SaleItem[]).filter(item => item.sale_id === sale.id) })));
    setNotes((noteRes.data ?? []) as Note[]); setSettings(settingRes.data ?? { reminders_enabled: true, reminder_lead_minutes: 60 });
  }
  async function createShop(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const name = new FormData(event.currentTarget).get("name")?.toString().trim(); if (!name || !user) return; const { data, error } = await supabase.from("pet_shops").insert({ name, owner_user_id: user.id }).select().single(); if (error) return fail(error); setShop(data); await loadWorkspace(data.id); notify("Pet shop creado. Ya podés comenzar a operar."); }
  async function signIn(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const email = new FormData(event.currentTarget).get("email")?.toString().trim(); if (!email) return; const { error } = await supabase.auth.signInWithOtp({ email, options: { emailRedirectTo: `${getPublicAppUrl()}/` } }); if (error) return fail(error); notify("Revisá tu correo para continuar con el enlace de acceso."); }
  async function signOut() { await supabase.auth.signOut(); setUser(null); setShop(null); setProducts([]); }

  const isCreator = user?.email === "nitsugamon@gmail.com";
  useEffect(() => { if (view === "diagnostics" && !isCreator) setView("summary"); }, [view, isCreator]);
  if (loading) return <div className="splash"><LoaderCircle className="spin" />Preparando PetFlow…</div>;
  if (!user) return <AuthCard onSubmit={signIn} notice={notice} />;
  if (!shop) return <ShopSetup onSubmit={createShop} notice={notice} />;
  const visibleSections = sections.filter((section) => section.id !== "diagnostics" || isCreator);
  const unread = notes.filter(note => !note.read_at).length;
  return <main className="app-shell"><aside className="side"><div className="brand"><PawPrint /><span>pet<span>flow</span></span></div><p className="shop-name">{shop.name}</p><nav>{visibleSections.map(section => { const Icon = section.icon; return <button key={section.id} className={view === section.id ? "nav-active" : ""} onClick={() => setView(section.id)}><Icon />{section.label}{section.id === "alerts" && unread ? <b>{unread}</b> : null}</button>; })}</nav><button className="logout" onClick={signOut}><LogOut />Cerrar sesión</button></aside><section className="content"><header className="topbar"><div><p className="kicker">OPERACIÓN DIARIA · {new Date().toLocaleDateString("es-AR", { weekday: "long", day: "numeric", month: "long" })}</p><h1>{sections.find(section => section.id === view)?.label}</h1></div><button className="primary" onClick={() => setModal("appointment")}><Plus />Nuevo turno</button></header>{view === "summary" && <Summary products={products} sales={sales} appointments={appointments} notes={notes} setView={setView} />} {view === "inventory" && <Inventory products={products} edit={(product: Product) => { setEditing(product); setModal("product"); }} add={() => { setEditing(null); setModal("product"); }} reload={loadWorkspace} fail={fail} shopId={shop.id} />} {view === "pos" && <PointOfSale products={products.filter(product => product.active)} clients={clients} shop={shop} reload={loadWorkspace} fail={fail} showTicket={(sale: Sale) => { setSelectedTicket(sale); setModal("ticket"); }} />} {view === "sales" && <SalesHistory sales={sales} showTicket={(sale: Sale) => { setSelectedTicket(sale); setModal("ticket"); }} />} {view === "clients" && <ClientsPanel clients={clients} sales={sales} selected={selectedClient} select={setSelectedClient} add={() => setModal("client")} addPet={(client: Client) => { setSelectedClient(client); setModal("pet"); }} />} {view === "agenda" && <Agenda appointments={appointments} clients={clients} setModal={setModal} reload={loadWorkspace} fail={fail} shopId={shop.id} />} {view === "cash" && <CashPanel shopId={shop.id} fail={fail} />} {view === "alerts" && <Alerts notes={notes} settings={settings} shopId={shop.id} reload={loadWorkspace} fail={fail} />} {view === "diagnostics" && isCreator && <DiagnosticsPanel results={diagnostics} run={() => runDiagnostics(shop.id)} />} </section>{modal === "product" && <ProductModal product={editing} shopId={shop.id} close={() => setModal(null)} reload={loadWorkspace} fail={fail} />} {modal === "client" && <ClientModal shopId={shop.id} close={() => setModal(null)} reload={loadWorkspace} fail={fail} />} {modal === "pet" && <PetModal shopId={shop.id} clients={clients} selected={selectedClient} close={() => setModal(null)} reload={loadWorkspace} fail={fail} />} {modal === "appointment" && <AppointmentModal shopId={shop.id} clients={clients} close={() => setModal(null)} reload={loadWorkspace} fail={fail} />} {modal === "ticket" && selectedTicket && <TicketModal ticket={selectedTicket} shopName={shop.name} close={() => setModal(null)} />} {notice && <div className="toast"><CheckCircle2 />{notice}</div>}</main>;
}

function AuthCard({ onSubmit, notice }: any) { return <main className="entry"><section className="entry-card"><div className="logo-mark"><PawPrint /></div><p className="kicker">GESTIÓN INTELIGENTE PARA PET SHOPS</p><h1>Todo lo que tu negocio necesita, en un solo flujo.</h1><p>Ingresá con tu correo para gestionar clientes, inventario, ventas, turnos y avisos con datos aislados por negocio.</p><form onSubmit={onSubmit}><label>Correo electrónico<input name="email" type="email" placeholder="nombre@negocio.com" required /></label><button className="primary full">Enviar enlace de acceso</button></form>{notice && <p className="form-note">{notice}</p>}</section></main>; }
function ShopSetup({ onSubmit, notice }: any) { return <main className="entry"><section className="entry-card"><div className="logo-mark"><PawPrint /></div><p className="kicker">BIENVENIDO A PETFLOW</p><h1>Creá el espacio de tu pet shop.</h1><p>Tu primer usuario quedará configurado como propietario. Los datos se guardarán separados de los demás negocios.</p><form onSubmit={onSubmit}><label>Nombre del pet shop<input name="name" minLength={2} placeholder="Ej. Patitas del Sur" required /></label><button className="primary full">Crear mi pet shop</button></form>{notice && <p className="form-note">{notice}</p>}</section></main>; }
function Summary({ products, sales, appointments, notes, setView }: any) { const today = new Date().toDateString(); const todaySales = sales.filter((sale: Sale) => new Date(sale.created_at).toDateString() === today); const low = products.filter((p: Product) => p.stock <= p.min_stock && p.active); const todayAppointments = appointments.filter((a: Appointment) => new Date(a.scheduled_at).toDateString() === today); const total = todaySales.reduce((sum: number, sale: Sale) => sum + Number(sale.total), 0); return <div className="stack"><section className="hero"><div><p className="kicker">PANEL OPERATIVO</p><h2>Las decisiones del día, a simple vista.</h2><p>Ventas, atención y reposición en una vista diseñada para avanzar rápido.</p></div><PawPrint className="hero-paw" /></section><div className="metrics"><Metric icon={<CircleDollarSign />} label="Ventas de hoy" value={formatter.format(total)} detail={`${todaySales.length} comprobantes`} /><Metric icon={<ShoppingCart />} label="Pedidos cobrados" value={todaySales.length} detail="Movimientos confirmados" /><Metric icon={<PackageSearch />} label="Stock a revisar" value={low.length} detail="Productos al mínimo" /><Metric icon={<CalendarDays />} label="Turnos de hoy" value={todayAppointments.length} detail="Servicios programados" /></div><div className="cards-grid"><Panel title="Próximos servicios" action="Abrir agenda" onAction={() => setView("agenda")}>{todayAppointments.length ? todayAppointments.slice(0, 5).map((a: Appointment) => <div className="row" key={a.id}><span className="time">{new Date(a.scheduled_at).toLocaleTimeString("es-AR", { hour: "2-digit", minute: "2-digit" })}</span><div><strong>{a.service}</strong><small>{statusLabel(a.status)}</small></div><span className="badge">{statusLabel(a.status)}</span></div>) : <Empty icon={<CalendarDays />} text="No hay turnos para hoy." />}</Panel><Panel title="Reposición" action="Ver inventario" onAction={() => setView("inventory")}>{low.length ? low.slice(0, 5).map((p: Product) => <div className="row" key={p.id}><div><strong>{p.name}</strong><small>Mínimo: {p.min_stock} unidades</small></div><span className="danger-pill">{p.stock}</span></div>) : <Empty icon={<CheckCircle2 />} text="Todo el inventario está en orden." />}</Panel><Panel title="Últimas ventas" action="Historial" onAction={() => setView("sales")}>{sales.length ? sales.slice(0, 5).map((sale: Sale) => <div className="row" key={sale.id}><div><strong>Venta #{sale.id.slice(0, 6).toUpperCase()}</strong><small>{new Date(sale.created_at).toLocaleString("es-AR")}</small></div><strong>{formatter.format(Number(sale.total))}</strong></div>) : <Empty icon={<ReceiptText />} text="Las ventas cobradas aparecerán aquí." />}</Panel><Panel title="Alertas activas" action="Gestionar" onAction={() => setView("alerts")}>{notes.filter((note: Note) => !note.read_at).length ? notes.filter((note: Note) => !note.read_at).slice(0, 4).map((note: Note) => <div className="row" key={note.id}><Bell className="icon-muted" /><div><strong>{note.title}</strong><small>{note.content}</small></div></div>) : <Empty icon={<Bell />} text="No hay alertas pendientes." />}</Panel></div></div>; }
function Metric({ icon, label, value, detail }: any) { return <article className="metric"><div>{icon}</div><p>{label}</p><strong>{value}</strong><small>{detail}</small></article>; }
function Panel({ title, action, onAction, children }: any) { return <section className="panel"><div className="panel-head"><h3>{title}</h3><button onClick={onAction}>{action}</button></div>{children}</section>; }
function Empty({ icon, text }: any) { return <div className="empty">{icon}<span>{text}</span></div>; }

function Inventory({ products, add, edit, reload, fail, shopId }: any) { const [query, setQuery] = useState(""); const [category, setCategory] = useState("all"); const [state, setState] = useState("all"); const visible = products.filter((product: Product) => `${product.name} ${product.sku || ""}`.toLowerCase().includes(query.toLowerCase()) && (category === "all" || product.category === category) && (state === "all" || (state === "active" && product.active) || (state === "inactive" && !product.active) || (state === "low" && product.active && product.stock <= product.min_stock))); async function adjust(product: Product, adjustment: number) { const { error } = await supabase.rpc("adjust_product_stock", { p_pet_shop_id: shopId, p_product_id: product.id, p_adjustment: adjustment }); if (error) return fail(error); await reload(); } return <div className="stack"><section className="toolbar"><label className="search"><Search /><input value={query} onChange={event => setQuery(event.target.value)} placeholder="Buscar por producto o SKU" /></label><select value={category} onChange={event => setCategory(event.target.value)} aria-label="Filtrar por categoría"><option value="all">Todas las categorías</option>{categories.map(item => <option key={item} value={item}>{item}</option>)}</select><select value={state} onChange={event => setState(event.target.value)} aria-label="Filtrar por estado"><option value="all">Todos los estados</option><option value="active">Activos</option><option value="low">Para reponer</option><option value="inactive">Inactivos</option></select><button className="primary" onClick={add}><Plus />Agregar producto</button></section><section className="table-panel"><div className="table-title"><div><p className="kicker">CATÁLOGO</p><h2>{visible.length} productos visibles</h2></div><p>Editar datos y ajustar existencias desde una misma tabla.</p></div><div className="table-wrap"><table><thead><tr><th>Producto</th><th>Categoría</th><th>Precio</th><th>Existencias</th><th>Estado</th><th aria-label="Acciones" /></tr></thead><tbody>{visible.map((product: Product) => <tr key={product.id}><td><strong>{product.name}</strong><small>{product.sku || "Sin SKU"}</small></td><td><span className="badge">{product.category}</span></td><td>{formatter.format(Number(product.sale_price))}</td><td><div className="stepper"><button disabled={product.stock === 0} onClick={() => adjust(product, -1)}>−</button><b>{product.stock}</b><button onClick={() => adjust(product, 1)}>+</button></div></td><td><span className={product.active ? (product.stock <= product.min_stock ? "danger-pill" : "success-pill") : "muted-pill"}>{product.active ? product.stock <= product.min_stock ? "Reponer" : "Disponible" : "Inactivo"}</span></td><td><button className="icon-button" onClick={() => edit(product)} aria-label={`Editar ${product.name}`}><Edit3 /></button></td></tr>)}</tbody></table></div></section></div>; }

function PointOfSale({ products, clients, shop, reload, fail, showTicket }: any) { const [cart, setCart] = useState<CartLine[]>([]); const [clientId, setClientId] = useState(""); const [method, setMethod] = useState("cash"); const [query, setQuery] = useState(""); const total = cart.reduce((sum, line) => sum + Number(line.sale_price) * line.quantity, 0); const add = (product: Product) => setCart(current => { const found = current.find(line => line.id === product.id); if (found) return found.quantity >= product.stock ? current : current.map(line => line.id === product.id ? { ...line, quantity: line.quantity + 1 } : line); return product.stock ? [...current, { ...product, quantity: 1 }] : current; }); async function confirm() { if (!cart.length) return; let items; try { items = prepareSaleRequest(cart.map(line => ({ productId: line.id, quantity: line.quantity, availableStock: line.stock }))); } catch (error) { return fail(error); } const { data, error } = await supabase.rpc("create_sale", { p_pet_shop_id: shop.id, p_client_id: clientId || null, p_payment_method: method, p_items: items }); if (error) return fail(error); const [saleResult, itemResult] = await Promise.all([supabase.from("sales").select("*").eq("id", data.sale_id).single(), supabase.from("sale_items").select("*").eq("sale_id", data.sale_id)]); await reload(); setCart([]); if (saleResult.error || itemResult.error) return fail(saleResult.error || itemResult.error); const client = clients.find((current: Client) => current.id === saleResult.data.client_id); showTicket({ ...saleResult.data, client, items: itemResult.data }); } return <div className="pos-layout"><section><div className="toolbar"><label className="search"><Search /><input value={query} onChange={event => setQuery(event.target.value)} placeholder="Buscar producto para el pedido" /></label></div><div className="product-grid">{products.filter((product: Product) => product.name.toLowerCase().includes(query.toLowerCase())).map((product: Product) => <button className="product-card" key={product.id} disabled={!product.stock} onClick={() => add(product)}><span>{product.category}</span><strong>{product.name}</strong><small>{product.stock} disponibles</small><b>{formatter.format(Number(product.sale_price))}</b></button>)}</div></section><aside className="ticket"><div className="ticket-head"><ReceiptText /><div><p className="kicker">PEDIDO ACTUAL</p><h2>Ticket de venta</h2></div></div><div className="ticket-lines">{cart.length ? cart.map(line => <div className="ticket-line" key={line.id}><div><strong>{line.name}</strong><small>{formatter.format(Number(line.sale_price))} c/u</small></div><div className="stepper"><button onClick={() => setCart(cart.map(item => item.id === line.id ? { ...item, quantity: Math.max(1, item.quantity - 1) } : item))}>−</button><b>{line.quantity}</b><button disabled={line.quantity >= line.stock} onClick={() => setCart(cart.map(item => item.id === line.id ? { ...item, quantity: item.quantity + 1 } : item))}>+</button></div><strong>{formatter.format(Number(line.sale_price) * line.quantity)}</strong></div>) : <Empty icon={<ShoppingCart />} text="Elegí productos para comenzar a cobrar." />}</div><label>Cliente (opcional)<select value={clientId} onChange={event => setClientId(event.target.value)}><option value="">Venta sin asociar</option>{clients.map((client: Client) => <option key={client.id} value={client.id}>{client.full_name}</option>)}</select></label><p className="label">Medio de pago</p><div className="pay-tabs">{["cash", "card", "transfer", "other"].map(item => <button key={item} className={method === item ? "selected" : ""} onClick={() => setMethod(item)}>{paymentLabel(item)}</button>)}</div><div className="total"><span>Total a cobrar</span><b>{formatter.format(total)}</b></div><button className="primary full" disabled={!cart.length} onClick={confirm}>Confirmar venta<ChevronDown /></button></aside></div>; }
function SalesHistory({ sales, showTicket }: any) { const [open, setOpen] = useState<string | null>(null); return <section className="table-panel"><div className="table-title"><div><p className="kicker">CONTROL COMERCIAL</p><h2>Historial completo de ventas</h2></div><p>Consultá el detalle y descargá o imprimí cada comprobante.</p></div><div className="table-wrap"><table><thead><tr><th>Fecha</th><th>Cliente</th><th>Pago</th><th>Total</th><th>Detalle</th><th /></tr></thead><tbody>{sales.map((sale: Sale) => <><tr key={sale.id}><td>{new Date(sale.created_at).toLocaleString("es-AR")}</td><td>{sale.client?.full_name || "Venta sin asociar"}</td><td><span className="badge">{paymentLabel(sale.payment_method)}</span></td><td><strong>{formatter.format(Number(sale.total))}</strong></td><td><button className="text-button" onClick={() => setOpen(open === sale.id ? null : sale.id)}>{open === sale.id ? "Ocultar" : `${sale.items.length} ítems`}</button></td><td><button className="icon-button" onClick={() => showTicket(sale)} aria-label="Abrir ticket"><ReceiptText /></button></td></tr>{open === sale.id && <tr className="details" key={`${sale.id}-detail`}><td colSpan={6}>{sale.items.map(item => <div key={`${sale.id}-${item.product_name}`} className="item-detail"><span>{item.quantity} × {item.product_name}</span><span>{formatter.format(Number(item.line_total))}</span></div>)}</td></tr>}</>)}</tbody></table></div>{!sales.length && <Empty icon={<ReceiptText />} text="Todavía no hay ventas registradas." />}</section>; }
function ClientsPanel({ clients, sales, selected, select, add, addPet }: any) { const [query, setQuery] = useState(""); const visible = clients.filter((client: Client) => `${client.full_name} ${client.phone || ""} ${client.pets.map(pet => pet.name).join(" ")}`.toLowerCase().includes(query.toLowerCase())); const clientSales = sales.filter((sale: Sale) => sale.client_id === selected?.id); return <div className="stack"><section className="toolbar"><label className="search"><Search /><input value={query} onChange={event => setQuery(event.target.value)} placeholder="Buscar por tutor o mascota" /></label><button className="primary" onClick={add}><Plus />Nuevo cliente</button></section><div className="clients-workspace"><div className="client-grid">{visible.map((client: Client) => <article className="client-card" key={client.id}><button className="client-main" onClick={() => select(client)}><div className="avatar">{client.full_name[0]}</div><div><h3>{client.full_name}</h3><p>{client.phone || client.email || "Sin datos de contacto"}</p></div></button><div className="pet-tags">{client.pets.length ? client.pets.map(pet => <span key={pet.id}><PawPrint />{pet.name} · {pet.species}</span>) : <span className="muted-pill">Sin mascotas</span>}</div><button className="text-button" onClick={() => addPet(client)}><Plus />Añadir mascota</button></article>)}</div><aside className="panel client-detail">{selected ? <><div className="panel-head"><div><p className="kicker">FICHA DEL CLIENTE</p><h2>{selected.full_name}</h2></div><button className="icon-button" onClick={() => select(null)} aria-label="Cerrar ficha"><X /></button></div><div className="contact-detail"><p><span>Teléfono</span>{selected.phone || "No registrado"}</p><p><span>Correo</span>{selected.email || "No registrado"}</p></div><div className="detail-section"><div className="panel-head"><h3>Mascotas</h3><button onClick={() => addPet(selected)}><Plus />Añadir</button></div>{selected.pets.length ? selected.pets.map((pet: Pet) => <div className="detail-row" key={pet.id}><PawPrint /><div><strong>{pet.name}</strong><small>{pet.species}{pet.breed ? ` · ${pet.breed}` : ""}</small></div></div>) : <p className="empty-copy">Aún no hay mascotas asociadas.</p>}</div><div className="detail-section"><div className="panel-head"><h3>Compras recientes</h3><span className="badge">{clientSales.length}</span></div>{clientSales.length ? clientSales.slice(0, 6).map((sale: Sale) => <div className="detail-row" key={sale.id}><ReceiptText /><div><strong>{new Date(sale.created_at).toLocaleDateString("es-AR")}</strong><small>{paymentLabel(sale.payment_method)}</small></div><b>{formatter.format(Number(sale.total))}</b></div>) : <p className="empty-copy">No hay compras registradas.</p>}</div></> : <Empty icon={<Users />} text="Seleccioná un cliente para consultar su ficha e historial." />}</aside></div></div>; }
function Agenda({ appointments, clients, setModal, reload, fail, shopId }: any) { const [day, setDay] = useState(new Date().toISOString().slice(0, 10)); const clientMap = new Map<string, Client>(clients.map((client: Client) => [client.id, client] as [string, Client])); const list = appointments.filter((appointment: Appointment) => appointment.scheduled_at.slice(0, 10) === day); async function setStatus(appointment: Appointment, status: string) { const { error } = await supabase.rpc("update_appointment_status", { p_pet_shop_id: shopId, p_appointment_id: appointment.id, p_status: status }); if (error) return fail(error); await reload(); } return <div className="agenda"><section className="panel"><div className="panel-head"><div><p className="kicker">VISTA DIARIA</p><h2>{new Date(`${day}T12:00`).toLocaleDateString("es-AR", { weekday: "long", day: "numeric", month: "long" })}</h2></div><input type="date" value={day} onChange={event => setDay(event.target.value)} /></div>{list.length ? list.map((appointment: Appointment) => { const client = clientMap.get(appointment.client_id); const pet = client?.pets.find((current: Pet) => current.id === appointment.pet_id); return <article className="appointment" key={appointment.id}><time>{new Date(appointment.scheduled_at).toLocaleTimeString("es-AR", { hour: "2-digit", minute: "2-digit" })}</time><div><h3>{pet?.name || "Mascota"}</h3><p>{client?.full_name || "Cliente"} · {appointment.service}</p></div><span className="badge">{statusLabel(appointment.status)}</span><select value={appointment.status} onChange={event => setStatus(appointment, event.target.value)}>{["scheduled", "confirmed", "in_progress", "completed", "cancelled", "no_show"].map(status => <option key={status} value={status}>{statusLabel(status)}</option>)}</select></article>; }) : <Empty icon={<CalendarDays />} text="No hay servicios agendados para este día." />}</section><aside className="agenda-callout"><CalendarDays /><p className="kicker">SERVICIOS</p><h2>Una agenda ordenada mejora cada atención.</h2><p>Creá turnos, sumá nuevos clientes sin salir del flujo y actualizá el estado mientras atendés.</p><button className="primary full" onClick={() => setModal("appointment")}><Plus />Agendar servicio</button></aside></div>; }
function Alerts({ notes, settings, shopId, reload, fail }: any) { const [enabled, setEnabled] = useState(settings.reminders_enabled); const [lead, setLead] = useState(settings.reminder_lead_minutes); async function save() { const { error } = await supabase.from("notification_settings").upsert({ pet_shop_id: shopId, reminders_enabled: enabled, reminder_lead_minutes: Number(lead) }); if (error) return fail(error); await reload(); } async function read(note: Note) { if (note.read_at) return; const { error } = await supabase.from("notifications").update({ read_at: new Date().toISOString() }).eq("id", note.id); if (error) return fail(error); await reload(); } return <div className="alerts"><section className="panel"><div className="panel-head"><div><p className="kicker">CENTRO DE AVISOS</p><h2>Actividad del responsable</h2></div><span className="badge">{notes.filter((note: Note) => !note.read_at).length} sin leer</span></div>{notes.length ? notes.map((note: Note) => <button className={note.read_at ? "notification" : "notification unread"} key={note.id} onClick={() => read(note)}><Bell /><div><strong>{note.title}</strong><p>{note.content}</p></div><small>{new Date(note.created_at).toLocaleDateString("es-AR")}</small></button>) : <Empty icon={<Bell />} text="Los recordatorios y cambios de estado aparecerán aquí." />}</section><aside className="reminder"><Bell /><p className="kicker">RECORDATORIOS</p><h2>El responsable, siempre al tanto.</h2><p>La bandeja conserva cambios y recordatorios. Cada turno sólo se notifica una vez.</p><label className="switch-line"><span><b>Recordatorios de turnos</b><small>Notificar antes del servicio</small></span><input checked={enabled} type="checkbox" onChange={event => setEnabled(event.target.checked)} /></label><label>Anticipación<select value={lead} onChange={event => setLead(event.target.value)}>{[15, 30, 60, 120].map(value => <option key={value} value={value}>{value < 60 ? `${value} minutos antes` : `${value / 60} hora antes`}</option>)}</select></label><button className="primary full" onClick={save}>Guardar preferencias</button><p className="hint">El trabajo de servidor ejecuta los recordatorios configurados, marca el turno antes de crear el aviso y así evita duplicados.</p></aside></div>; }

function CashPanel({ shopId, fail }: { shopId: string; fail: (error: any) => void }) {
  const [register, setRegister] = useState<any>(null);
  const [opening, setOpening] = useState("0");
  const [amount, setAmount] = useState("");
  const [busy, setBusy] = useState(false);
  async function load() { const { data, error } = await supabase.from("cash_registers").select("*").eq("pet_shop_id", shopId).eq("status", "open").maybeSingle(); if (error) return fail(error); setRegister(data); }
  useEffect(() => { void load(); }, [shopId]);
  async function open() { setBusy(true); const { data, error } = await supabase.rpc("open_cash_register", { p_pet_shop_id: shopId, p_opening_amount: Number(opening) }); setBusy(false); if (error) return fail(error); setRegister(data); }
  async function movement(type: "cash_in" | "cash_out") { if (!register || Number(amount) <= 0) return; setBusy(true); const { error } = await supabase.rpc("record_cash_movement", { p_pet_shop_id: shopId, p_register_id: register.id, p_type: type, p_payment_method: "cash", p_amount: Number(amount), p_note: type === "cash_in" ? "Ingreso manual" : "Retiro manual" }); setBusy(false); if (error) return fail(error); setAmount(""); }
  async function close() { if (!register || Number(amount) < 0) return; setBusy(true); const { data, error } = await supabase.rpc("close_cash_register", { p_pet_shop_id: shopId, p_register_id: register.id, p_counted_cash: Number(amount), p_note: "Cierre confirmado desde PetFlow" }); setBusy(false); if (error) return fail(error); setRegister(data); }
  return <div className="stack"><section className="hero"><div><p className="kicker">CONTROL DE CAJA</p><h2>{register ? "Turno abierto y controlado." : "Abrí la caja para comenzar."}</h2><p>Todos los ingresos, retiros y cierres quedan auditados por usuario y negocio.</p></div><WalletCards className="hero-paw" /></section><section className="panel cash-panel">{!register ? <><h2>Apertura de caja</h2><Field label="Monto inicial"><input type="number" min="0" value={opening} onChange={e => setOpening(e.target.value)} /></Field><button className="primary" disabled={busy} onClick={open}>Abrir caja</button></> : <><div className="panel-head"><div><p className="kicker">CAJA ABIERTA</p><h2>Turno iniciado</h2></div><span className="success-pill">ACTIVA</span></div><p className="cash-note">Apertura: <strong>{formatter.format(Number(register.opening_amount))}</strong></p><Field label="Movimiento o efectivo contado"><input type="number" min="0" value={amount} onChange={e => setAmount(e.target.value)} /></Field><div className="button-row"><button className="secondary" disabled={busy} onClick={() => movement("cash_in")}>Registrar ingreso</button><button className="secondary" disabled={busy} onClick={() => movement("cash_out")}>Registrar retiro</button><button className="primary" disabled={busy} onClick={close}>Confirmar cierre</button></div><p className="hint">El cierre calcula la diferencia entre efectivo esperado y contado y la registra en auditoría.</p></>}</section></div>;
}

function DiagnosticsPanel({ results, run }: { results: DiagnosticResult[]; run: () => void }) { const summary = summarizeDiagnostics(results); return <div className="stack"><section className="hero diagnostics-hero"><div><p className="kicker">MODO CREADOR · MONITOREO PRIVADO</p><h2>Salud del sistema sin interrumpir la operación.</h2><p>Las comprobaciones son de lectura, aisladas y no crean ventas ni modifican datos.</p></div><ShieldCheck className="hero-paw" /></section><section className="metrics"><Metric icon={<Activity />} label="Pruebas ejecutadas" value={summary.total} detail="Última ejecución" /><Metric icon={<CheckCircle2 />} label="Correctas" value={summary.passed} detail="Sin incidencias" /><Metric icon={<Bell />} label="Advertencias" value={summary.warnings} detail="Revisar cuando puedas" /><Metric icon={<ShieldCheck />} label="Críticas" value={summary.critical} detail="Requieren atención" /></section><section className="panel"><div className="panel-head"><div><p className="kicker">VERIFICACIÓN NO DESTRUCTIVA</p><h2>Componentes del sistema</h2></div><button className="primary" onClick={run}><Activity />Ejecutar pruebas</button></div>{results.length ? results.map((result) => <div className="diagnostic-row" key={result.name}><span className={result.ok ? "success-pill" : result.severity === "critical" ? "danger-pill" : "warning-pill"}>{result.ok ? "OK" : result.severity.toUpperCase()}</span><div><strong>{result.name}</strong><small>{result.detail}</small></div><small>{result.durationMs} ms</small></div>) : <Empty icon={<Activity />} text="Todavía no hay resultados. Ejecutá la primera verificación." />}</section></div>; }
function Modal({ title, children, close }: any) { return <div className="modal-backdrop"><section className="modal"><button className="modal-close" onClick={close} aria-label="Cerrar"><X /></button><p className="kicker">PETFLOW</p><h2>{title}</h2>{children}</section></div>; }
function ProductModal({ product, shopId, close, reload, fail }: any) { const [form, setForm] = useState(product ? { ...product, stock: String(product.stock), min_stock: String(product.min_stock), cost_price: String(product.cost_price), sale_price: String(product.sale_price), sku: product.sku || "" } : emptyProduct); const patch = (key: string, value: any) => setForm((current: any) => ({ ...current, [key]: value })); async function submit(event: FormEvent) { event.preventDefault(); try { validateProductDraft({ name: form.name, category: form.category, stock: Number(form.stock), minStock: Number(form.min_stock), costPrice: Number(form.cost_price), salePrice: Number(form.sale_price) }); } catch (error) { return fail(error); } const payload = { pet_shop_id: shopId, name: form.name.trim(), sku: form.sku.trim() || null, category: form.category, stock: Number(form.stock), min_stock: Number(form.min_stock), cost_price: Number(form.cost_price), sale_price: Number(form.sale_price), active: form.active }; const action = product ? supabase.from("products").update(payload).eq("id", product.id) : supabase.from("products").insert(payload); const { error } = await action; if (error) return fail(error); await reload(); close(); } return <Modal close={close} title={product ? "Editar artículo" : "Nuevo producto"}><form className="form-grid" onSubmit={submit}><Field label="Nombre"><input value={form.name} onChange={e => patch("name", e.target.value)} required /></Field><Field label="SKU"><input value={form.sku} onChange={e => patch("sku", e.target.value)} /></Field><Field label="Categoría"><select value={form.category} onChange={e => patch("category", e.target.value)}>{categories.map(category => <option key={category}>{category}</option>)}</select></Field><Field label="Existencias"><input min="0" type="number" value={form.stock} onChange={e => patch("stock", e.target.value)} required /></Field><Field label="Stock mínimo"><input min="0" type="number" value={form.min_stock} onChange={e => patch("min_stock", e.target.value)} required /></Field><Field label="Costo unitario"><input min="0" step="0.01" type="number" value={form.cost_price} onChange={e => patch("cost_price", e.target.value)} required /></Field><Field label="Precio de venta"><input min="0" step="0.01" type="number" value={form.sale_price} onChange={e => patch("sale_price", e.target.value)} required /></Field><label className="check"><input type="checkbox" checked={form.active} onChange={e => patch("active", e.target.checked)} />Artículo activo y disponible para vender</label><button className="primary full">{product ? "Guardar cambios" : "Crear producto"}</button></form></Modal>; }
function ClientModal({ shopId, close, reload, fail }: any) { const [form, setForm] = useState({ full_name: "", phone: "", email: "", notes: "" }); const patch = (key: string, value: string) => setForm(current => ({ ...current, [key]: value })); async function submit(event: FormEvent) { event.preventDefault(); const { error } = await supabase.from("clients").insert({ pet_shop_id: shopId, ...form }); if (error) return fail(error); await reload(); close(); } return <Modal close={close} title="Nuevo cliente"><form className="form-grid" onSubmit={submit}><Field label="Nombre completo"><input required value={form.full_name} onChange={e => patch("full_name", e.target.value)} /></Field><Field label="Teléfono"><input value={form.phone} onChange={e => patch("phone", e.target.value)} /></Field><Field label="Correo"><input type="email" value={form.email} onChange={e => patch("email", e.target.value)} /></Field><Field label="Notas"><textarea value={form.notes} onChange={e => patch("notes", e.target.value)} /></Field><button className="primary full">Crear cliente</button></form></Modal>; }
function PetModal({ shopId, clients, selected, close, reload, fail }: any) { const [form, setForm] = useState({ client_id: selected?.id || "", name: "", species: "Perro", breed: "", notes: "" }); const patch = (key: string, value: string) => setForm(current => ({ ...current, [key]: value })); async function submit(event: FormEvent) { event.preventDefault(); const { error } = await supabase.from("pets").insert({ pet_shop_id: shopId, ...form }); if (error) return fail(error); await reload(); close(); } return <Modal close={close} title="Asociar mascota"><form className="form-grid" onSubmit={submit}><Field label="Tutor"><select value={form.client_id} onChange={e => patch("client_id", e.target.value)} required><option value="">Elegir cliente</option>{clients.map((client: Client) => <option key={client.id} value={client.id}>{client.full_name}</option>)}</select></Field><Field label="Nombre"><input required value={form.name} onChange={e => patch("name", e.target.value)} /></Field><Field label="Especie"><select value={form.species} onChange={e => patch("species", e.target.value)}>{["Perro", "Gato", "Ave", "Otro"].map(species => <option key={species}>{species}</option>)}</select></Field><Field label="Raza"><input value={form.breed} onChange={e => patch("breed", e.target.value)} /></Field><Field label="Notas"><textarea value={form.notes} onChange={e => patch("notes", e.target.value)} /></Field><button className="primary full">Guardar mascota</button></form></Modal>; }
function AppointmentModal({ shopId, clients, close, reload, fail }: any) { const [mode, setMode] = useState<"existing" | "new">("existing"); const [form, setForm] = useState<any>({ client_id: "", pet_id: "", client_full_name: "", client_phone: "", client_email: "", client_notes: "", pet_name: "", pet_species: "Perro", pet_breed: "", pet_notes: "", service: services[0], scheduled_at: new Date(Date.now() + 3600000).toISOString().slice(0, 16), duration_minutes: "60", appointment_notes: "" }); const patch = (key: string, value: string) => setForm((current: any) => ({ ...current, [key]: value })); const pets = clients.find((client: Client) => client.id === form.client_id)?.pets || []; async function submit(event: FormEvent) { event.preventDefault(); const common = { p_pet_shop_id: shopId, p_service: form.service, p_scheduled_at: new Date(form.scheduled_at).toISOString(), p_duration_minutes: Number(form.duration_minutes) }; const params = mode === "existing" ? { ...common, p_client_id: form.client_id, p_pet_id: form.pet_id, p_notes: form.appointment_notes } : { ...common, p_client_full_name: form.client_full_name, p_client_phone: form.client_phone, p_client_email: form.client_email, p_client_notes: form.client_notes, p_pet_name: form.pet_name, p_pet_species: form.pet_species, p_pet_breed: form.pet_breed, p_pet_notes: form.pet_notes, p_appointment_notes: form.appointment_notes }; const { error } = await supabase.rpc(mode === "existing" ? "create_appointment" : "create_appointment_with_new_client", params); if (error) return fail(error); await reload(); close(); } return <Modal close={close} title="Agendar servicio"><p className="modal-copy">Podés seleccionar un tutor existente o dar de alta un cliente y su mascota sin abandonar este turno.</p><div className="mode-switch"><button className={mode === "existing" ? "selected" : ""} onClick={() => setMode("existing")}>Cliente existente</button><button className={mode === "new" ? "selected" : ""} onClick={() => setMode("new")}>Nuevo cliente y mascota</button></div><form className="form-grid" onSubmit={submit}>{mode === "existing" ? <><Field label="Tutor"><select value={form.client_id} onChange={e => { patch("client_id", e.target.value); patch("pet_id", ""); }} required><option value="">Elegir cliente</option>{clients.map((client: Client) => <option key={client.id} value={client.id}>{client.full_name}</option>)}</select></Field><Field label="Mascota"><select value={form.pet_id} onChange={e => patch("pet_id", e.target.value)} disabled={!form.client_id} required><option value="">Elegir mascota</option>{pets.map((pet: Pet) => <option key={pet.id} value={pet.id}>{pet.name} · {pet.species}</option>)}</select></Field></> : <><p className="form-section">Datos del tutor</p><Field label="Nombre completo"><input required value={form.client_full_name} onChange={e => patch("client_full_name", e.target.value)} /></Field><Field label="Teléfono"><input value={form.client_phone} onChange={e => patch("client_phone", e.target.value)} /></Field><Field label="Correo"><input type="email" value={form.client_email} onChange={e => patch("client_email", e.target.value)} /></Field><Field label="Notas del tutor"><textarea value={form.client_notes} onChange={e => patch("client_notes", e.target.value)} /></Field><p className="form-section">Datos de la mascota</p><Field label="Nombre"><input required value={form.pet_name} onChange={e => patch("pet_name", e.target.value)} /></Field><Field label="Especie"><select value={form.pet_species} onChange={e => patch("pet_species", e.target.value)}>{["Perro", "Gato", "Ave", "Otro"].map(species => <option key={species}>{species}</option>)}</select></Field><Field label="Raza"><input value={form.pet_breed} onChange={e => patch("pet_breed", e.target.value)} /></Field><Field label="Notas de la mascota"><textarea value={form.pet_notes} onChange={e => patch("pet_notes", e.target.value)} /></Field></>}<Field label="Servicio"><select value={form.service} onChange={e => patch("service", e.target.value)}>{services.map(service => <option key={service}>{service}</option>)}</select></Field><Field label="Fecha y hora"><input required type="datetime-local" value={form.scheduled_at} onChange={e => patch("scheduled_at", e.target.value)} /></Field><Field label="Duración (minutos)"><input required min="5" max="720" type="number" value={form.duration_minutes} onChange={e => patch("duration_minutes", e.target.value)} /></Field><Field label="Notas del turno"><textarea value={form.appointment_notes} onChange={e => patch("appointment_notes", e.target.value)} /></Field><button className="primary full">Guardar turno</button></form></Modal>; }
function TicketModal({ ticket, shopName, close }: any) { return <Modal close={close} title="Ticket de venta"><section className="ticket-preview"><h3>{shopName}</h3><p>Ticket #{ticket.id.slice(0, 8).toUpperCase()} · {new Date(ticket.created_at).toLocaleString("es-AR")}</p>{ticket.items.map((item: SaleItem) => <div className="ticket-line" key={item.product_name}><span>{item.quantity} × {item.product_name}</span><strong>{formatter.format(Number(item.line_total))}</strong></div>)}<div className="total"><span>Total</span><b>{formatter.format(Number(ticket.total))}</b></div><p>Pago: {paymentLabel(ticket.payment_method)}</p></section><div className="ticket-actions"><button className="secondary" onClick={() => printTicket(ticket, shopName)}><Printer />Imprimir</button><button className="primary" onClick={() => downloadTicketPdf(ticket, shopName)}><Download />Descargar PDF</button></div></Modal>; }
function Field({ label, children }: any) { return <label className="field"><span>{label}</span>{children}</label>; }
function statusLabel(status: string) { return ({ scheduled: "Programado", confirmed: "Confirmado", in_progress: "En servicio", completed: "Completado", cancelled: "Cancelado", no_show: "No asistió" } as Record<string, string>)[status] ?? status; }
